#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static void usage(void) {
    puts("USAGE");
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        usage();
        return 0;
    }
    // Parse shift amount (allow optional leading '+' or '-')
    char *p = argv[1];
    int sign = 1;
    if (*p == '-') {
        sign = -1;
        p++;
    } else if (*p == '+') {
        p++;
    }
    if (*p == '\0') {
        usage();
        return 0;
    }
    long val = 0;
    while (*p) {
        if (*p < '0' || *p > '9') {
            usage();
            return 0;
        }
        val = val * 10 + (*p - '0');
        p++;
    }
    int shift = (int)(sign * val);
    // Normalize shift to range 0-25
    shift %= 26;
    if (shift < 0) shift += 26;

    char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) { // original program limit
        usage();
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (char)((c - 'A' + shift) % 26 + 'A');
        } else if (c >= 'a' && c <= 'z') {
            c = (char)((c - 'a' + shift) % 26 + 'a');
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
